def _board_open_resource_file():
    # A private delete-on-close disk snapshot pins this exact version. Keeping
    # the original open can block legacy Windows os.replace despite share=7.
    # No persistent cache, user content or decoded catalog is copied to RAM.
    import tempfile
    import shutil
    snapshot=tempfile.TemporaryFile(mode='w+b',prefix='GPT6-Board-resources-',buffering=0)
    try:
        with open(__file__,'rb') as original:
            if _br_os.fstat(original.fileno()).st_size != _BOARD_RESOURCE_FILE_SIZE:
                raise ImportError('Board single-file size differs')
            shutil.copyfileobj(original,snapshot,64*1024)
        snapshot.seek(0)
        return snapshot
    except BaseException:
        snapshot.close();raise
_BOARD_RESOURCE_FILE=_board_open_resource_file()
_BOARD_RESOURCE_LOCK=_br_threading.RLock()
_br_atexit.register(_BOARD_RESOURCE_FILE.close)
if _br_os.fstat(_BOARD_RESOURCE_FILE.fileno()).st_size != _BOARD_RESOURCE_FILE_SIZE:
    raise ImportError('Board single-file size differs')

def _board_resource_packed(name):
    if _BOARD_RESOURCE_FORMAT != 1:
        raise ImportError('Unsupported Board resource format')
    offset, length, raw_length, digest, packed_digest = _BOARD_RESOURCE_INDEX[name]
    if not (0 <= offset < _BOARD_RESOURCE_FILE_SIZE and 0 < length <= _BOARD_RESOURCE_FILE_SIZE-offset):
        raise ImportError('Invalid Board resource bounds: '+name)
    try:
        with _BOARD_RESOURCE_LOCK:
            source=_BOARD_RESOURCE_FILE
            if _br_os.fstat(source.fileno()).st_size != _BOARD_RESOURCE_FILE_SIZE:
                raise ImportError('Board single-file size differs')
            source.seek(offset)
            packed=source.read(length)
        if len(packed)!=length or _br_hash.sha256(packed).hexdigest()!=packed_digest:
            raise ImportError('Board resource checksum differs: '+name)
        return packed
    except OSError as exc:
        raise ImportError('Board resource cannot be read: '+name) from exc

def _board_resource_bytes(name):
    packed=_board_resource_packed(name)
    raw_length=_BOARD_RESOURCE_INDEX[name][2]
    try:
        stream=_br_zlib.decompressobj()
        raw=stream.decompress(_br_b64.b64decode(packed,validate=True),raw_length+1)
        if (len(raw)!=raw_length or not stream.eof or stream.unused_data or stream.unconsumed_tail
                or _br_hash.sha256(raw).hexdigest()!=_BOARD_RESOURCE_INDEX[name][3]):
            raise ValueError('invalid decompressed resource')
        return raw
    except (ValueError,_br_zlib.error) as exc:
        raise ImportError('Board resource is damaged: '+name) from exc

def _board_resource_text(name):
    try:return _board_resource_bytes(name).decode('utf-8')
    except UnicodeError as exc:raise ImportError('Board resource text is damaged: '+name) from exc

class _BoardResourceSources(_BRMapping):
    """The original mutable source mapping, with no decoded-source cache."""
    def __init__(self):
        self._names=dict(_BOARD_RESOURCE_MODULES);self._names['board_log_runtime']=None
        self._overrides={}
    def __getitem__(self,name):
        if name=='board_log_runtime':return _BOARD_LOG_RUNTIME_SOURCE
        if name in self._overrides:
            digest,packed=self._overrides[name]
            raw=_br_zlib.decompress(_br_b64.b64decode(packed,validate=True))
            if _br_hash.sha256(raw).hexdigest()!=digest:raise ImportError('Embedded source is damaged: '+name)
            return raw.decode('utf-8')
        return _board_resource_text(self._names[name])
    def __setitem__(self,name,source):
        if not isinstance(name,str) or not isinstance(source,str):
            raise TypeError('Embedded module names and sources must be strings.')
        raw=source.encode('utf-8')
        self._overrides[name]=(_br_hash.sha256(raw).hexdigest(),_br_b64.b64encode(_br_zlib.compress(raw,9)))
        self._names.setdefault(name,None)
    def __delitem__(self,name):
        del self._names[name]
        self._overrides.pop(name,None)
    def __iter__(self):return iter(self._names)
    def __len__(self):return len(self._names)
    def __contains__(self,name):return name in self._names
    def copy(self):return {name:self[name] for name in self}

if __name__=='__main__' and len(_br_sys.argv)==3 and _br_sys.argv[1]=='--ct-hotkey-worker':
    _worker={'__name__':'ce_runtime_hotkey','__file__':__file__}
    exec(compile(_board_resource_text('early_ct'),__file__+'::ce_runtime_hotkey','exec'),_worker)
    raise SystemExit(_worker['worker_main'](int(_br_sys.argv[2])))
if __name__=='__main__' and len(_br_sys.argv)==4 and _br_sys.argv[1]=='--freecam-mouse-worker':
    _worker={'__name__':'freecam_mouse_worker','__file__':__file__}
